(7, 1, 'INV260709-3866', 6, 'new test', '09922202003', 3, 'trst sakes', '2026-07-09', 2184.00, 0.00, 0.00, 0.00, 0.00, 2184.00, 2184.00, 0.00, 'cash', 'completed', NULL, 'Goods once sold cannot be returned or exchanged.\n\nWarranty on Products: 1 Year Warranty.\n\nWarranty T&C - Warranty does not cover physical damage like liquid spill, water spill, burn, high voltage damage, display broken or crack, display line, display patch, speaker damage, keys broken or any other physical damage. Loss of data, software or any other information.\n\nExclusions from Warranty - Consumable parts such as batteries are not covered.\n\nService Warranty - Covers the cost of service/labour. Any parts replaced will be charged at actuals.\n\nDelivery charges may be additional.', 2, '2026-07-09 07:27:26', '2026-07-09 07:48:06'),
(8, 1, 'INV260709-9207', 1, 'nova thor', '8109010648', 3, 'trst sakes', '2026-07-09', 2118.00, 0.00, 0.00, 0.00, 0.00, 2118.00, 1500.00, 618.00, 'cash', 'partial', NULL, 'Goods once sold cannot be returned or exchanged.\n\nWarranty is applicable only if provided by brand/manufacturer.\n\nWarranty does not cover physical damage, burnt, liquid damage, broken cable, broken connector or misuse.\n\nReplacement or service will be as per company warranty policy.\n\nDelivery charges may be additional.', 2, '2026-07-09 07:49:18', '2026-07-09 07:49:18'),
(9, 1, 'INV260709-0638', 3, 'Kapil gamer', '9999999999', 3, 'trst sakes', '2026-07-09', 1376.00, 0.00, 0.00, 0.00, 0.00, 1376.00, 1376.00, 0.00, 'cash', 'completed', NULL, 'Gaming charges are non-refundable once session starts.\n\nCustomer is responsible for any physical damage to controller, headset, keyboard, mouse, monitor, console or gaming accessories.\n\nFood, drinks and rough handling are not allowed near gaming setup.\n\nSession time will be counted from start time. Extra time will be charged as per store pricing.\n\nEronix Technologies is not responsible for saved game progress or online account issues.', 2, '2026-07-09 08:39:34', '2026-07-09 08:39:34');
